// eslint-disable-next-line @typescript-eslint/ban-ts-comment -- The migrated integration extends third-party classes with no published contracts.
// @ts-nocheck -- Argon supplies its panel base classes and WFRP4e supplies dynamic actor documents at runtime.

import {
  deriveArgonMovementDisplay,
  formatArgonMovementValue,
} from "../../../functions/integrations/enhancedcombathud/movement";
import { getConfiguredSkills } from "./argon-helpers";
import { ARGON_ACTOR_CONFIG_TEMPLATE, CHARACTERISTICS } from "./constants";

function requireMovementNumber(value, field) {
  const numericValue =
    typeof value === "number"
      ? value
      : typeof value === "string" && value.trim()
        ? Number(value)
        : Number.NaN;

  if (!Number.isFinite(numericValue)) {
    throw new Error(`WFRP actor movement ${field} must be numeric.`);
  }

  return numericValue;
}

function requireMovementUnits(value) {
  if (typeof value !== "string" || !value.trim()) {
    throw new Error("The active scene must define movement units for the Argon movement HUD.");
  }

  return value;
}

export function createArgonPanels(CoreHUD) {
  const ARGON = CoreHUD.ARGON;

  class WFRPPortraitPanel extends ARGON.PORTRAIT.PortraitPanel {
    get configurationTemplate() {
      return ARGON_ACTOR_CONFIG_TEMPLATE;
    }

    async _getButtons() {
      const buttons = await super._getButtons();
      const openSheetButton = buttons.find((button) => button.id === "open-sheet");

      if (openSheetButton) {
        openSheetButton.icon = "fas fa-user";
        openSheetButton.label = "Open Actor Sheet";
      }

      return buttons;
    }

    get description() {
      if (this.actor.type === "character") return this.actor.details.career.value;
      return this.actor.details.species.value;
    }

    get isDead() {
      return Boolean(this.actor.hasCondition("dead"));
    }

    async getStatBlocks() {
      const wounds = this.actor.status.wounds;
      const advantage = this.actor.status.advantage.value;
      const woundRatio = wounds.max ? wounds.value / wounds.max : 0;
      const woundColor = woundRatio > 0.5 ? "#00ff64" : woundRatio > 0.25 ? "#ffc800" : "#ff3232";

      return [
        [
          { text: `${game.i18n.localize("wfrp4e-compatibility-box.Argon.Portrait.Wounds")}: ` },
          { text: wounds.value, color: woundColor },
          { text: ` / ${wounds.max}` },
        ],
        [
          { text: `${game.i18n.localize("wfrp4e-compatibility-box.Argon.Portrait.Advantage")}: ` },
          { text: advantage },
        ],
      ];
    }
  }

  class WFRPDrawerPanel extends ARGON.DRAWER.DrawerPanel {
    get title() {
      return "wfrp4e-compatibility-box.Argon.Drawer.Title";
    }

    get categories() {
      const characteristics = CHARACTERISTICS.map((key) => {
        const characteristic = this.actor.characteristics[key];
        const roll = async () => {
          const test = await this.actor.setupCharacteristic(key);
          await test.roll();
        };

        return new ARGON.DRAWER.DrawerButton([
          { label: game.i18n.localize(game.wfrp4e.config.characteristics[key]), onClick: roll },
          { label: characteristic.value, onClick: roll },
          { label: characteristic.bonus, onClick: roll },
        ]);
      });

      const skills = getConfiguredSkills(this.actor)
        .sort((a, b) => a.name.localeCompare(b.name))
        .map((skill) => {
          const roll = async () => {
            const test = await this.actor.setupSkill(skill);
            await test.roll();
          };

          return new ARGON.DRAWER.DrawerButton([
            { label: skill.name, onClick: roll },
            { label: skill.total.value, onClick: roll },
            {
              label: game.i18n.localize(
                game.wfrp4e.config.characteristicsAbbrev[skill.characteristic.value],
              ),
              onClick: roll,
            },
          ]);
        });

      return [
        {
          gridCols: "3fr 1fr 1fr",
          captions: [
            { label: "wfrp4e-compatibility-box.Argon.Drawer.Characteristics", align: "left" },
            { label: "wfrp4e-compatibility-box.Argon.Drawer.Value", align: "center" },
            { label: "wfrp4e-compatibility-box.Argon.Drawer.Bonus", align: "center" },
          ],
          buttons: characteristics,
        },
        {
          gridCols: "minmax(0, 3fr) minmax(3.5rem, 1fr) minmax(3.5rem, 1fr)",
          captions: [
            { label: "wfrp4e-compatibility-box.Argon.Drawer.Skills", align: "left" },
            { label: "wfrp4e-compatibility-box.Argon.Drawer.Value", align: "center" },
            { label: "wfrp4e-compatibility-box.Argon.Drawer.CharacteristicShort", align: "center" },
          ],
          buttons: skills,
        },
      ];
    }
  }

  class WFRPMovementHud extends ARGON.MovementHud {
    get moveScore() {
      return requireMovementNumber(this.actor.details.move.value, "value");
    }

    get movementMax() {
      return requireMovementNumber(this.actor.details.move.run, "run distance");
    }

    get movementUnits() {
      return requireMovementUnits(canvas.scene.grid.units);
    }

    get movementColor() {
      if (!this.movementMax) return "base-movement";
      return super.movementColor;
    }

    updateMovementUsed() {
      const movementHistory = this.token.document.movementHistory;
      if (!Array.isArray(movementHistory)) {
        throw new Error(
          "The active token must expose movement history for the Argon movement HUD.",
        );
      }

      this.movementUsed = Math.round(
        movementHistory.reduce((acc, movement, index) => {
          acc += requireMovementNumber(movement?.cost, `history entry ${index + 1} cost`);
          return acc;
        }, 0),
      );
    }

    updateMovement() {
      this.updateMovementUsed();

      const runDistance = this.movementMax;
      const movement = deriveArgonMovementDisplay(this.moveScore, runDistance, this.movementUsed);
      const movementColor = this.movementColor;
      const movementLabel = game.i18n.localize(
        movement.movementBlock === 0
          ? "wfrp4e-compatibility-box.Argon.Movement.Run"
          : "wfrp4e-compatibility-box.Argon.Movement.Sprint",
      );

      const barsContainer = this.element.querySelector(".movement-spaces");
      let newHtml = "";
      for (let i = 0; i < movement.availableBubbles; i++) {
        newHtml += `<div class="movement-space ${movementColor}"></div>`;
      }
      for (let i = 0; i < movement.usedBubbles; i++) {
        newHtml += `<div class="movement-space"></div>`;
      }

      this.element.querySelector(".movement-current").innerText =
        `${movementLabel} ${formatArgonMovementValue(movement.remainingDistance)} ${this.movementUnits}`;
      this.element.querySelector(".movement-max").innerText =
        `${formatArgonMovementValue(movement.blockLimit)} ${this.movementUnits}`;
      this.element.title = game.i18n.format("wfrp4e-compatibility-box.Argon.Movement.Hint", {
        move: this.moveScore,
        distance: formatArgonMovementValue(movement.bubbleDistance),
        units: this.movementUnits,
      });
      barsContainer.innerHTML = newHtml;
    }
  }

  return { WFRPDrawerPanel, WFRPMovementHud, WFRPPortraitPanel };
}
