import type { ArgonMovementDisplay } from "../../../types/integrations/enhancedcombathud/Argon";

function assertArgonMovementValue(value: number, field: string): void {
  if (!Number.isFinite(value) || value < 0) {
    throw new Error(`Argon movement ${field} must be a finite, non-negative number.`);
  }
}

export function deriveArgonMovementDisplay(
  moveScore: number,
  movementMax: number,
  movementUsed: number,
): ArgonMovementDisplay {
  assertArgonMovementValue(moveScore, "move score");
  assertArgonMovementValue(movementMax, "maximum distance");
  assertArgonMovementValue(movementUsed, "used distance");

  const bubbleCount = Math.max(Math.round(moveScore), 1);
  const bubbleDistance = movementMax > 0 ? movementMax / bubbleCount : 0;
  const movementBlock = movementMax ? Math.floor(movementUsed / movementMax) : 0;
  const movementUsedInBlock = movementMax ? movementUsed % movementMax : 0;
  const usedBubbles = bubbleDistance
    ? Math.min(Math.ceil(movementUsedInBlock / bubbleDistance), bubbleCount)
    : 0;
  const blockLimit = (movementBlock + 1) * movementMax;

  return {
    availableBubbles: Math.max(bubbleCount - usedBubbles, 0),
    blockLimit,
    bubbleDistance,
    movementBlock,
    remainingDistance: Math.max(blockLimit - movementUsed, 0),
    usedBubbles,
  };
}

export function formatArgonMovementValue(value: number): string {
  assertArgonMovementValue(value, "display distance");
  return Number.isInteger(value) ? String(value) : value.toFixed(1);
}
