import type { OptionalFeatureId, OptionalFeatureStatus } from "../../types/module/OptionalFeature";
import { isModuleActive } from "../integrations/is-module-active";
import { isOptionalFeatureEnabled } from "./is-optional-feature-enabled";
import { OPTIONAL_FEATURES } from "./optional-features";

export function getOptionalFeatureStatuses(): OptionalFeatureStatus[] {
  return (
    Object.entries(OPTIONAL_FEATURES) as [
      OptionalFeatureId,
      (typeof OPTIONAL_FEATURES)[OptionalFeatureId],
    ][]
  ).map(([id, feature]) => ({
    available: isModuleActive(feature.targetModuleId),
    enabled: isOptionalFeatureEnabled(id),
    id,
    targetModuleId: feature.targetModuleId,
  }));
}
