import { registerModuleApi } from "../api/register-module-api";
import { registerArgonCombatHudIntegration } from "../integrations/enhancedcombathud/register-integration";
import { registerPaperDollIntegration } from "../integrations/fvtt-paper-doll-ui/register-integration";
import { registerModuleSettings } from "../settings/register-module-settings";

export function registerModuleHooks(): void {
  Hooks.once("init", () => {
    registerModuleSettings();
    registerModuleApi();
    registerArgonCombatHudIntegration();
    registerPaperDollIntegration();
  });
}
