import type {
  PaperDollSlotChange,
  PaperDollSlotState,
} from "../../../types/patches/paper-doll/Equipment";

function getSlotValue(state: PaperDollSlotState, slotId: string, slotIndex: string): string | null {
  return state[slotId]?.[slotIndex] ?? null;
}

export function findSlotChanges(
  before: PaperDollSlotState,
  after: PaperDollSlotState,
): PaperDollSlotChange[] {
  const slotIds = new Set([...Object.keys(before), ...Object.keys(after)]);
  const changes: PaperDollSlotChange[] = [];

  for (const slotId of slotIds) {
    const indexes = new Set([
      ...Object.keys(before[slotId] ?? {}),
      ...Object.keys(after[slotId] ?? {}),
    ]);

    for (const index of indexes) {
      const from = getSlotValue(before, slotId, index);
      const to = getSlotValue(after, slotId, index);

      if (from !== to) {
        changes.push({
          from,
          slotId,
          slotIndex: Number(index),
          to,
        });
      }
    }
  }

  return changes;
}
