import {
  ARMOUR_SLOT_IDS,
  WEAPON_SLOT_IDS,
  type ArmourSlotId,
  type ArmourEquipmentSnapshot,
  type EquipmentSnapshot,
  type PaperDollSlotAssignment,
  type WeaponEquipmentSnapshot,
  type WfrpArmourLocation,
  type WfrpHand,
} from "../../../types/patches/paper-doll/Equipment";

const ARMOUR_LOCATIONS: readonly WfrpArmourLocation[] = [
  "head",
  "lArm",
  "rArm",
  "lLeg",
  "rLeg",
  "body",
];

const ARMOUR_SLOT_LOCATIONS: Record<ArmourSlotId, readonly WfrpArmourLocation[]> = {
  BODY: ["body"],
  BOOTS: ["lLeg", "rLeg"],
  GLOVES: ["lArm", "rArm"],
  HEAD: ["head"],
};

interface ArmourCandidate {
  coverage: number;
  item: ArmourEquipmentSnapshot;
  points: number;
}

function compareArmour(a: ArmourCandidate, b: ArmourCandidate): number {
  return (
    b.coverage - a.coverage ||
    b.points - a.points ||
    a.item.name.localeCompare(b.item.name) ||
    a.item.id.localeCompare(b.item.id)
  );
}

function getArmourPointsForSlot(item: ArmourEquipmentSnapshot, slotId: ArmourSlotId): number {
  return Math.max(...ARMOUR_SLOT_LOCATIONS[slotId].map((location) => item.armourPoints[location]));
}

function getArmourCoverageForSlot(item: ArmourEquipmentSnapshot, slotId: ArmourSlotId): number {
  return ARMOUR_SLOT_LOCATIONS[slotId].filter((location) => item.armourPoints[location] > 0).length;
}

function compareArmourForSlot(
  slotId: ArmourSlotId,
  a: ArmourCandidate,
  b: ArmourCandidate,
): number {
  return (
    getArmourPointsForSlot(b.item, slotId) - getArmourPointsForSlot(a.item, slotId) ||
    getArmourCoverageForSlot(b.item, slotId) - getArmourCoverageForSlot(a.item, slotId) ||
    compareArmour(a, b)
  );
}

function isEquippedArmour(item: EquipmentSnapshot): item is ArmourEquipmentSnapshot {
  return item.type === "armour" && item.equipped;
}

function makeArmourCandidate(item: ArmourEquipmentSnapshot): ArmourCandidate {
  const points = item.armourPoints;
  const protectedLocations = ARMOUR_LOCATIONS.filter((location) => points[location] > 0);

  return {
    coverage: protectedLocations.length,
    item,
    points: protectedLocations.reduce((total, location) => total + points[location], 0),
  };
}

function getArmourAssignments(items: readonly EquipmentSnapshot[]): PaperDollSlotAssignment[] {
  const candidates = items.filter(isEquippedArmour).map(makeArmourCandidate);

  return ARMOUR_SLOT_IDS.flatMap((slotId) => {
    const candidate = candidates
      .filter((entry) => getArmourPointsForSlot(entry.item, slotId) > 0)
      .sort((a, b) => compareArmourForSlot(slotId, a, b))[0];

    return candidate ? [{ slotId, uuid: candidate.item.uuid }] : [];
  });
}

function getWeaponHand(item: WeaponEquipmentSnapshot, mainHand: WfrpHand): WfrpHand | "both" {
  if (item.twoHanded) {
    return "both";
  }

  if (item.offhand) {
    return mainHand === "l" ? "r" : "l";
  }

  return mainHand;
}

function compareWeapons(a: WeaponEquipmentSnapshot, b: WeaponEquipmentSnapshot): number {
  return (
    Number(b.twoHanded) - Number(a.twoHanded) ||
    a.name.localeCompare(b.name) ||
    a.id.localeCompare(b.id)
  );
}

function getWeaponAssignments(
  items: readonly EquipmentSnapshot[],
  mainHand: WfrpHand,
): PaperDollSlotAssignment[] {
  const equippedWeapons = items
    .filter((item): item is WeaponEquipmentSnapshot => item.type === "weapon" && item.equipped)
    .sort(compareWeapons);

  return WEAPON_SLOT_IDS.flatMap((slotId) => {
    const hand = slotId === "MAIN_LEFT" ? "l" : "r";
    const item = equippedWeapons.find((entry) => {
      const weaponHand = getWeaponHand(entry, mainHand);
      return weaponHand === "both" || weaponHand === hand;
    });

    return item ? [{ slotId, uuid: item.uuid }] : [];
  });
}

export function deriveEquipmentSlots(
  items: readonly EquipmentSnapshot[],
  mainHand: WfrpHand,
): PaperDollSlotAssignment[] {
  return [...getArmourAssignments(items), ...getWeaponAssignments(items, mainHand)];
}
